mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.4) * p.xz;
  p.yz = rot(time * 0.2) * p.yz;
  float d = 100.0;
  for (float a = 0.0; a < 6.28; a += 0.35) {
    vec3 pt = vec3(sin(a * 2.0 + time) * 1.2, cos(a * 3.0) * 0.8, sin(a * 4.0) * 1.0);
    d = min(d, length(p - pt) - 0.06);
  }
  return d;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float glow = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    glow += 0.015 / (0.05 + abs(d));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(1.2, 0.3, 0.8) * (0.8 + 0.3 * bass);
  ret = col;
}
